import { Camera, Mesh, Scene, Pipeline, Setup, Render, Plane, Texture, Loader, Vec2 } from '../../../src'
import Controls from './Controls'
import vs from './vs.wgsl?raw'
import fs from './fs.wgsl?raw'

export default async () => {
	const gpu = new Setup()
	await gpu.create()

	const loader = new Loader()
	const video = await loader.fromUrl({
		url: 'https://videos.ctfassets.net/nbkc2e2m0dev/4fk8EgeZmNeUkvgraJU65R/2609e4ac80f79543488f18240d4dc242/1.mp4',
	})

	const texture = Texture.create({ gpu, source: video.element })
	const camera = new Camera()
	const geometry = new Plane({ width: 500, height: 500 })

	const uniforms = {
		box: { value: new Vec2(geometry.width, geometry.height) },
		asset: { value: new Vec2(texture.width, texture.height) },
	}

	const mesh = new Mesh({ gpu, geometry, texture, uniforms })
	const scene = new Scene({ gpu, camera, mesh })
	const pipeline = new Pipeline({ gpu, vs, fs, scene })
	const render = new Render({ gpu, pipeline })

	render.raf(() => {
		mesh.rotation.y += 0.01
		scene.update()
	})

	new Controls({ camera })

	/* Destroy RAF and raycast on route change */
	window.addEventListener('route-change', () => {
		render.destroy()
	})
}

